TRANSLATIONS_162 = {
    # ==================== CG_162_01 ====================
    'CG_162_01.4': 'Màn Một',
    'CG_162_01.5': 'Cái Tên Của Nàng (Phần I)',
    'CG_162_01.6': 'Một cảm giác quen thuộc đến kỳ lạ, một cơ hội để đổi thay—tất cả khởi đầu từ chính cái tên của nàng.',
    'CG_162_01.49': 'Hây!==W== Ha!==W== Vút!',
    'CG_162_01.60': 'Uầy... Thanh kiếm này cứ như có suy nghĩ riêng vậy. Dù mình làm cách nào đi nữa, vung kiếm vẫn cứ thấy gượng gạo sao ấy...',
    'CG_162_01.62': 'Thử lại lần nữa xem nào. Cứ thả lỏng để lưỡi kiếm tự dẫn lối...==W== Hây!==W== Vút...==W== Oái?!==W==',
    'CG_162_01.94': 'Ái ui... Chà, ngã đẹp mắt ghê chưa. Quê chết đi được.==W== Haha, may mà chẳng có ai nhìn thấy...',
    'CG_162_01.104': 'Tư thế của bạn hoàn toàn sai rồi đấy.',
    'CG_162_01.114': '... Hét to gớm nhỉ. Phổi của bạn hoạt động tốt thật đấy.',
    'CG_162_01.120': 'Nói thật đấy, đi đứng gì mà chẳng phát ra chút tiếng động nào thế... Làm tôi hết hồn, suýt thì bay mất nửa cái mạng.',
    'CG_162_01.123': 'Tôi chỉ lần theo tiếng động mà đến thôi... Nay bạn dậy sớm khác thường nhỉ. Chẳng giống tính bạn chút nào.',
    'CG_162_01.125': 'À, tôi chỉ đang tập luyện chút thôi mà.',
    'CG_162_01.128': 'Tập luyện? Việc đó đâu giống điều mà một Thị Giả Cầu Nguyện cần phải làm.',
    'CG_162_01.131': 'Ờ thì... Tôi nghĩ mình cũng nên học chút kỹ năng tự vệ. Nếu đi tuần tra mà tôi cứ vô dụng thế này, bạn lại phải bận tâm bọc lót cho tôi mất.',
    'CG_162_01.134': 'Đây là...==W== thế tấn mà một người bạn từng dạy tôi. Cậu ấy bảo nó rất hợp cho người mới bắt đầu.',
    'CG_162_01.144': 'Tinh thần đáng khen đấy, nhưng tập thế này thì vô ích thôi. Người bạn cứng đơ như khúc gỗ, chỉ tổ phí sức...==W== Khoan đã, bạn đã khởi động kỹ càng chưa đấy?',
    'CG_162_01.146': 'Ờ... Đại khái là rồi?',
    'CG_162_01.148': 'Thế tức là chưa đúng cách rồi. Cơ bắp của bạn đang bị căng cứng kìa. Thảo nào lại mất thăng bằng rồi ngã chổng vó ra đất như thế.',
    'CG_162_01.150': 'Bạn thấy hết rồi đấy à?!',
    'CG_162_01.157': 'Lại đây nào, chúng ta bắt đầu lại từ bài giãn cơ. Đứng tựa lưng vào lưng tôi thế này...==W== Giờ thì móc tay vào nhau đi.',
    'CG_162_01.163': 'Một,==W== hai,==W== ba...',
    'CG_162_01.168': '(X-Xương sống của mình đang kêu răng rắc đấy à?!)',
    'CG_162_01.172': 'Cứ như thế này. Đứng tựa lưng vào tôi...==B== Giờ thì khóa chặt cánh tay lại.',
    'CG_162_01.179': 'Cảm giác này quen thuộc quá... Giống hệt như hồi Noya giúp mình giãn cơ...',
    'CG_162_01.181': 'Động tác tiếp theo... Ngồi xuống và duỗi thẳng hai chân ra. Từ từ cúi gập người về phía trước, cố chạm vào mũi chân nào.',
    'CG_162_01.198': 'Khi cô ấy tựa vào lưng tôi, trọng lượng cơ thể chậm rãi đè xuống... Cảm giác hệt như ngày hôm ấy.',
    'CG_162_01.202': 'Ái, ái, đau, đau quá! Tôi xin hàng, tôi xin hàaaang!==W== Tôi xin hàng mà, Noya!',
    'CG_162_01.207': 'cắt đứt',
    'CG_162_01.211': 'A... Xin lỗi nhé. Tôi vô tình nhớ về một người bạn cũ, nên lỡ miệng buột ra thôi...',
    'CG_162_01.216': '... Dám gọi tôi bằng tên của người khác cơ đấy? Xem ra bạn vẫn còn thừa thãi sức lực lắm nhỉ. Để giúp bạn tập trung giãn cơ hơn nhé...',
    'CG_162_01.218': 'Tôi sẽ ấn mạnh thêm một chút nữa đấy!',
    'CG_162_01.220': 'Khoan, khoan, khoan đã! Tôi tập trung rồi! Tôi sẽ tập trung mà,==W== oaaaa!',
    'CG_162_01.230': 'Cơ thể bạn đã thấy thả lỏng hơn chút nào chưa?',
    'CG_162_01.231': 'Hộc... Hộc... Giờ chẳng còn là thả lỏng nữa rồi. Tôi cứ tưởng xương sống của mình sắp gãy làm đôi tới nơi...',
    'CG_162_01.233': 'Đừng lo. Cơ thể con người dẻo dai hơn bạn tưởng nhiều đấy...==W== Hửm?',
    'CG_162_01.236': 'Tiếng xe ngựa. Nghe như đang đi về hướng này. ==PLAYER_NAME==, mau trốn đi.',
    'CG_162_01.260': 'Kẻ Buôn Nô Lệ Khả Nghi',
    'CG_162_01.261': 'Được rồi, cho ngựa nghỉ ngơi ở đây một lát đi. Sau đó chúng ta sẽ đi thẳng tới trang viên của Lãnh chúa Caligula.',
    'CG_162_01.263': 'Kẻ Buôn Nô Lệ Nóng Tính',
    'CG_162_01.264': 'Rõ rồi!',
    'CG_162_01.270': 'Hê hê, lần này bắt được một món hàng thượng phẩm đấy. Chuyến này chắc chắn được giá lắm đây, đúng chứ?',
    'CG_162_01.271': 'Lãnh chúa Caligula lúc nào chẳng hào phóng chi đậm cho phụ nữ! Ngài ấy thậm chí còn sắp xếp sẵn cho chúng ta một con đường bí mật để vào thành nữa cơ mà. Nhờ thế công việc dễ thở hơn bao nhiêu. Đúng là vị cứu tinh của chúng ta.',
    'CG_162_01.281': 'Đó là... xe ngựa của bọn buôn nô lệ sao?',
    'CG_162_01.283': 'Có vẻ là vậy. Caligula... Tôi thật không ngờ hắn lại dính líu đến đường dây buôn bán nô lệ.',
    'CG_162_01.285': 'Bạn biết hắn ta à?',
    'CG_162_01.286': 'Cha hắn xuất thân từ Emor, là một thành viên của Viện Nguyên Lão. Gia tộc của bọn chúng sở hữu vô số điền trang trải khắp Filanis.',
    'CG_162_01.287': 'Ngoài mặt thì làm bộ phản đối chế độ nô lệ, nhưng sau lưng lại lén lút trục lợi từ sự bẩn thỉu này.==W== Thật không thể tha thứ được!==W==',
    'CG_162_01.289': '... Bạn muốn giải cứu những người nô lệ đó sao?',
    'CG_162_01.292': 'Tâm tư hiện rõ hết lên mặt bạn rồi kìa.',
    'CG_162_01.293': 'Nhưng tôi là Người Gác Đêm của Filanis. Tôi không có quyền hạn giải cứu nô lệ bên ngoài phạm vi ranh giới thành phố.',
    'CG_162_01.294': 'Đợi chúng đi qua cổng thành rồi mới chặn lại sao...? Không được. Nghe lời chúng nói thì đây chẳng phải lần giao dịch đầu tiên. Caligula chắc chắn sẽ có cách bưng bít phi tang.',
    'CG_162_01.296': 'Nếu không có chứng cứ xác thực, Đội Gác Đêm chẳng thể nào động đến gia quyến của một Nguyên Lão.',
    'CG_162_01.298': 'Nếu vậy thì, chỉ cần bạn tạm thời không làm Người Gác Đêm của Filanis trong giây lát... Vấn đề sẽ được giải quyết ngay, đúng không?',
    'CG_162_01.301': 'Ý bạn là sao?',
    'CG_162_01.303': 'Đơn giản thôi mà. Đám buôn nô lệ này đâu có bị Người Gác Đêm tấn công, chúng chỉ vô tình bị bọn thổ phỉ qua đường phục kích thôi. Ở ngoài Hoang Dã thế này, bị thổ phỉ nhắm tới là chuyện quá đỗi bình thường.',
    'CG_162_01.305': 'Đúng là vậy, nhưng làm sao tự nhiên lại có thổ phỉ xuất hiện đúng lúc thế này được...==W== Khoan đã, đừng nói với tôi là...',
    'CG_162_01.306': 'Chuẩn luôn. Chúng ta chính là lũ thổ phỉ đó!',
    'CG_162_01.307': 'Chúng ta ư? Một Người Gác Đêm lại đi giả dạng thổ phỉ... Thế này là hoàn toàn vượt qua giới hạn rồi đấy. Hành động này sẽ bôi nhọ danh dự của Đội Gác Đêm mất.',
    'CG_162_01.308': 'Vậy là bạn định cứ thế đứng nhìn sao?',
    'CG_162_01.311': 'Tôi nghĩ việc ngó lơ lương tâm của chính mình mới là vết nhơ lớn hơn nhiều đối với danh dự của bạn đấy.',
    'CG_162_01.315': 'Và nếu bạn thật sự nghĩ việc này là vượt quá ranh giới, thì này, đã có tôi ở đây vượt qua giới hạn đó cùng bạn rồi.',
    'CG_162_01.316': 'Lương tâm của tôi... ==PLAYER_NAME==, bạn có biết mình đang dụ dỗ một Người Gác Đêm đi lệch khỏi quỹ đạo không hả?',
    'CG_162_01.318': 'Nhưng mà... bạn nói đúng. Làm thôi nào!',
    'CG_162_01.321': 'Được rồi! Lên đường thôi!',
    'CG_162_01.326': 'Khu rừng này là của bọn ta, và con đường này cũng do bọn ta mở!',
    'CG_162_01.328': 'Muốn đi qua đây, thì phải để lại tiền mãi lộ!',
    'CG_162_01.333': 'Hê hê, xem ra hôm nay tóm được con cá lớn rồi! Muốn giữ mạng thì để hàng lại rồi biến đi!',
    'CG_162_01.334': 'Thổ phỉ ư?! To gan thật đấy. Các ngươi có biết đây là hàng của ai không hả? Chỉ nghe tên thôi cũng đủ khiến các ngươi run rẩy rồi!',
    'CG_162_01.338': 'Ta cóc cần biết là của ai. Hôm nay, món chiến lợi phẩm bất chính này thuộc về Boss!',
    'CG_162_01.340': 'Boss? Mày tự xưng là Boss đấy à? Hừ, tao sẽ nhớ kỹ cái tên này.==W== Tốt nhất là bọn mày nên bắt đầu chọn bia mộ cho mình đi là vừa.',
    'CG_162_01.352': 'Kẻ cần xây mộ chính là các ngươi đấy.',
    'CG_162_01.361': 'Hả? Kiếm... kiếm của tao... Sao lại gãy làm đôi thế này?!',
    'CG_162_01.365': 'Hê hê hê... Trừ khi các ngươi muốn Kỵ Sĩ Bóng Đêm của ta chém các ngươi thành hai mảnh,==W== thì cúp đuôi chạy lẹ đi là nước đi khôn ngoan nhất đấy.',
    'CG_162_01.371': 'Lũ Buôn Nô Lệ',
    'CG_162_01.372': 'Á á á! Chạy mau giữ mạaaang!',
    'CG_162_01.377': 'Hắc Kỵ Sĩ',
    'CG_162_01.378': 'Mọi người có ai bị thương không?',
    'CG_162_01.379': 'Nô Lệ Bị Bắt',
    'CG_162_01.380': 'Xin các người! Tôi sẽ làm bất cứ điều gì các người muốn, chỉ xin tha cho em gái tôi thôi!',
    'CG_162_01.381': 'Bình tĩnh đi nào. Chúng tôi không phải thổ phỉ đâu.',
    'CG_162_01.384': 'Cầm lấy số tiền này rồi chạy đi. Hãy đi về phía bắc tới Filanis. Cứ đi thẳng là chừng một tiếng nữa sẽ tới nơi.',
    'CG_162_01.385': 'Một khi đã bước vào bên trong tường thành, không tên buôn nô lệ nào dám đụng tới các bạn đâu.',
    'CG_162_01.386': 'Những Người Nô Lệ Được Cứu',
    'CG_162_01.387': 'Ôi... Cảm ơn ân nhân! Đa tạ ân nhân nhiều lắm!',
    'CG_162_01.391': 'Phù. Bọn họ chạy thoát cả rồi. Chỉ cần tới được Filanis là họ sẽ an toàn.',
    'CG_162_01.392': 'Ừ. Mà này, bạn diễn vai thổ phỉ trông cũng thuyết phục phết đấy chứ.',
    'CG_162_01.393': '... Tôi nên coi câu đó là lời xúc phạm à?',
    'CG_162_01.394': 'Đâu có đâu. Là lời khen thật lòng đấy.',
    'CG_162_01.395': 'Lời khen ư...? Tôi chẳng thấy việc đó có gì đáng để tự hào cả.',
    'CG_162_01.396': 'Thế còn cái trò nhảm nhí Kỵ Sĩ Bóng Đêm đó là thế nào vậy hả?',
    'CG_162_01.397': 'Có bí danh thì hành sự mới dễ chứ. Thấy chưa? Tôi cũng tự gọi mình là Boss đấy thôi, đúng không?',
    'CG_162_01.398': 'Nếu người ta có thể nhân danh Thánh Nữ Sa Ngã để đi làm điều xằng bậy, thì việc chúng ta dùng tên giả để hành hiệp trượng nghĩa cũng có hại gì đâu.',
    'CG_162_01.400': 'Hừm... Bởi vì đó là lựa chọn mà tôi sẽ không bao giờ hối hận.',
    'CG_162_01.402': 'Phải rồi... Nếu khi nãy cứ thế để mặc cho bọn buôn nô lệ rời đi, tôi biết chắc mình sẽ vô cùng ân hận.',
    'CG_162_01.404': 'Nên tôi chỉ thuận theo tiếng gọi của con tim mà hành động thôi. Chuyện đơn giản chỉ có vậy.',
    'CG_162_01.405': 'Dù bạn có bảo hành động đó là ti tiện đi chăng nữa, tôi vẫn sẽ luôn đưa ra lựa chọn khiến bản thân không phải nuối tiếc. Bất luận là lần nào đi nữa.',
    'CG_162_01.406': '... Ra là bạn đã suy nghĩ thấu đáo đến mức đó rồi.',
    'CG_162_01.407': 'Hả? Trong mắt bạn tôi là loại người nông cạn thế nào chứ?!',
    'CG_162_01.409': 'Khi một người bỗng nhiên đòi đi làm thổ phỉ, thì người bình thường nào cũng sẽ nghĩ người đó mất trí rồi thôi.',
    'CG_162_01.411': 'Nhưng mà...==W== Cảm ơn bạn đã giúp tôi nhé. Nếu không có bạn, có lẽ tôi chỉ biết trơ mắt đứng nhìn mà chẳng thể làm được gì. Và tôi biết chắc mình cũng sẽ hối hận vô cùng...',
    'CG_162_01.414': 'Cơ mà nói gì thì nói, chuyện vượt ranh giới chỉ được phép xảy ra hôm nay thôi đấy nhé! Vì danh tiếng của cả hai chúng ta, tuyệt đối không được hé răng nửa lời về những gì đã diễn ra ở đây đâu.',
    'CG_162_01.416': 'Nghĩa là chuyện này chỉ được có hai ta biết thôi đấy.==W== Thống nhất thế nhé?',
    'CG_162_01.417': 'Bí mật của riêng hai chúng ta sao...==W== À, tôi hiểu rồi.',
    'CG_162_01.420': 'À mà này...==W== Chuyện xảy ra ngày hôm nay...==W== Cậu làm ơn giữ kín làm bí mật nhỏ giữa hai đứa mình thôi được không?',
    'CG_162_01.423': 'Em sợ bị Iris cằn nhằn xé tai đúng không?',
    'CG_162_01.425': 'Nếu để bả mà đánh hơi được vụ này á,==W== là thể nào em cũng bị cấm bén mảng tới gần vô lăng của Loxy suốt hai tháng ròng rã cho mà xem!',
    'CG_162_01.427': 'Nghĩ lại thì, mình cũng từng hứa một điều tương tự với Noya...',
    'CG_162_01.428': 'Noya, Iris, Amber... Làm sao để tôi có thể tìm đường trở về bên các bạn đây...?',
    'CG_162_01.432': '<size=85%>Lại là cái tên đó nữa rồi... Noya. Có lẽ mình thực sự trông rất giống cô ấy.</size>',
    'CG_162_01.433': '<size=85%>Tự hỏi không biết... cô ấy là một người như thế nào nhỉ?</size>',

    # ==================== CG_162_02 ====================
    'CG_162_02.4': 'Hồi Hai',
    'CG_162_02.5': 'Cái Tên Của Nàng (Phần II)',
    'CG_162_02.6': 'Muốn được gần bên bạn hơn nữa, được sánh bước bên bạn, và trở thành người đồng hành mà bạn có thể gửi gắm niềm tin cậy.',
    'CG_162_02.33': 'Thêm một nhúm muối...==W== Áp chảo cho tới khi ngả màu vàng ươm...',
    'CG_162_02.49': 'Tôi về rồi đây. Thơm phức luôn...==W== Bạn đang nấu món gì thế?',
    'CG_162_02.55': 'Cá nướng đấy. Chờ một tí thôi, sắp xong rồi.',
    'CG_162_02.62': 'Hóa ra là làm như thế à...',
    'CG_162_02.66': 'S-Sao thế? Bạn nhìn chằm chằm làm tôi phân tâm quá đấy...==W== Đừng bảo là bạn ghét ăn cá nhé?',
    'CG_162_02.69': 'Không hề. Món gì được nấu ngon tôi đều ăn hết. Ý tôi không phải vậy đâu. Chỉ là... tôi có chuyện này muốn nhờ bạn.',
    'CG_162_02.71': 'Bạn có thể...==W== dạy tôi nấu ăn được không?',
    'CG_162_02.73': 'Được chứ, chuyện nhỏ mà. Nhưng sao tự dưng bạn lại muốn học thế?',
    'CG_162_02.74': 'Tôi không thể cứ để khách của mình vào bếp nấu nướng mãi được. Là chủ nhà, chăm sóc bạn chu đáo là bổn phận của tôi.',
    'CG_162_02.75': 'Tôi thật lòng không để bụng đâu...==W== Nhưng được thôi, nếu bạn muốn học, tôi sẽ chỉ dạy tận tình.',
    'CG_162_02.77': 'Nói trước là tôi sẽ không nương tay đâu đấy nhé. Chuẩn bị tinh thần đi.',
    'CG_162_02.78': 'Tất nhiên rồi. Nghiêm khắc thế tôi mới thích chứ.',
    'CG_162_02.85': 'Bắt đầu từ rau củ trước nhé. Cắt khoai tây thành từng miếng vừa ăn nào.',
    'CG_162_02.88': 'Rõ rồi. Miếng vừa ăn...',
    'CG_162_02.92': 'Khoan, dừng lại, dừng lại mau!',
    'CG_162_02.94': 'Sao thế bạn?',
    'CG_162_02.96': 'Khoan đã, bạn không gọt vỏ à? Mà mấy tảng khoai này to đùng thế kia, ai mà ăn cho nổi chứ?',
    'CG_162_02.99': 'Vỏ khoai ăn được mà. Còn nếu to quá thì cứ cắn làm đôi ra là xong.',
    'CG_162_02.101': 'Tôi công nhận là vỏ khoai không độc hại gì, nhưng ăn vào cảm giác gợn miệng lắm. Hơn nữa, củ to thế này nấu sẽ không chín đều đâu. Và quan trọng nhất là, ăn như thế khổ sở vô cùng!',
    'CG_162_02.103': 'Tôi không ngờ nấu nướng lại có nhiều chi tiết cần phải để tâm đến thế đấy...',
    'CG_162_02.105': 'Muốn có món ngon thì không được làm qua loa đại khái đâu. Để tôi thái cho. Bạn cứ đứng nhìn học hỏi trước đã.',
    'CG_162_02.111': 'Được rồi, rau củ đã mềm rồi đấy. Đến công đoạn nêm nếm. Bạn cho một lượng muối vừa ăn vào giúp tôi nhé.',
    'CG_162_02.115': 'Hiểu rồi. Lượng vừa ăn...',
    'CG_162_02.117': 'Giờ sao nữa?',
    'CG_162_02.120': 'Bạn cứ thế đổ cả hũ muối vào luôn đấy à? Sao không dùng thìa múc...?',
    'CG_162_02.121': 'Thế này nhanh hơn mà. Với lại, nếu đã bảo là "vừa ăn", chẳng phải có nghĩa là tôi thích nêm bao nhiêu tùy ý sao?',
    'CG_162_02.122': 'Ý đâu phải thế đâu trời...==W== Để tôi hỏi bạn câu này nhé, Alina. Bạn thích ăn mặn hay ăn thanh đạm?',
    'CG_162_02.125': 'Chắc là thanh đạm rồi.',
    'CG_162_02.126': 'Rõ rồi...==W== Được rồi, thế thì chỉ cần ngần này thôi. Nào, nếm thử một ngụm xem.',
    'CG_162_02.129': 'Ồ, ngon thật đấy...==W== Nếu bạn đã biết rõ phải nêm bao nhiêu, sao ngay từ đầu không nói thẳng ra luôn đi?',
    'CG_162_02.132': 'Bởi vì khẩu vị của mỗi người mỗi khác mà. Thế nên tôi mới bảo là "vừa ăn" đấy chứ.',
    'CG_162_02.133': 'Thấu hiểu sở thích khẩu vị của người cùng ăn, hiểu rõ tính chất của từng loại nguyên liệu...',
    'CG_162_02.135': 'Nắm vững tất cả những điều đó trước khi bắt tay vào bếp mới chính là bí quyết thực sự để có một bữa ăn ngon.',
    'CG_162_02.136': 'Hóa ra nấu nướng cũng đòi hỏi sự chuẩn xác tỉ mỉ hệt như khi vung kiếm vậy. Trước giờ tôi chưa từng biết điều đó đấy.',
    'CG_162_02.137': 'Haha, nói thật lòng thì tay nghề nửa mùa này của tôi cũng là học lỏm từ một người bạn cả thôi. Tôi chỉ bắt chước lại những gì cậu ấy từng dạy tôi.',
    'CG_162_02.138': 'Để tôi đoán nhé...==W== Là Noya đúng không?',
    'CG_162_02.139': 'Ừ. Mỗi món Noya nấu ra đều là một kiệt tác cả. Ngày trước cậu ấy hay dạy tôi lắm.',
    'CG_162_02.140': 'Ra là vậy...',
    'CG_162_02.141': 'Cô ấy là người như thế nào vậy... Người tên Noya đó ấy?',
    'CG_162_02.144': 'Bạn đã gọi nhầm tên tôi thành cô ấy không chỉ một lần đâu. Khó mà không tò mò cho được.',
    'CG_162_02.147': '... Cũng đúng thôi. Để xem nào, nên diễn tả thế nào nhỉ...',
    'CG_162_02.148': 'Chắc nụ cười của cậu ấy là điều đầu tiên tôi nghĩ tới. Năng lượng và sự ấm áp của Noya đã cứu rỗi tôi không biết bao nhiêu lần rồi.',
    'CG_162_02.149': 'Và cậu ấy lúc nào cũng quan tâm chăm sóc tôi hết mực. Đến món đồ uống khoái khẩu nhất, cậu ấy cũng sẵn lòng san sẻ cho tôi một nửa...',
    'CG_162_02.150': 'Lúc nào cũng che chở cho tôi. Đảm bảo tôi không bao giờ phải chịu chút thương tổn nào.',
    'CG_162_02.152': '... Vậy là bạn có ý nghĩa vô cùng to lớn đối với cô ấy sao?',
    'CG_162_02.153': 'Nhắc mới nhớ, cậu ấy đúng là từng nói một câu tương tự như thế.',
    'CG_162_02.154': 'Vậy à...==W== Thế còn cái thói quen hay lách luật của bạn thì sao? Cũng học từ cô ấy luôn đấy à?',
    'CG_162_02.155': 'À...==W== Chắc là thế rồi. Noya lúc nào cũng nghĩ ra những ý tưởng táo bạo nhất đời.',
    'CG_162_02.157': 'Như cái lần cậu ấy quyết định lái Loxy đâm thẳng vào một con Tinh Hài khổng lồ chẳng hạn. Lần đó suýt nữa thì dọa tôi mất mật.',
    'CG_162_02.159': 'Tinh Hài ư? Loxy là gì?',
    'CG_162_02.160': 'Ờ thì...==W== Cứ tưởng tượng cảnh lao xe ngựa hết tốc lực tông thẳng vào một con quái vật khổng lồ đi. Dễ hình dung hơn chưa?',
    'CG_162_02.164': 'Chiến thuật kiểu quái gì vậy chứ...?==W== Hoàn toàn liều lĩnh đến điên rồ.',
    'CG_162_02.165': 'Haha, ai nghe qua cũng sẽ nghĩ vậy thôi. Thế nhưng, cậu ấy vẫn xoay sở làm được đấy.',
    'CG_162_02.166': 'Kể từ dạo đó, tôi liền nhận ra một điều...==W== Rằng chỉ cần có Noya ở bên cạnh, dù chuyện có điên rồ hỗn loạn đến mức nào đi nữa, chúng tôi nhất định cũng sẽ tìm ra lối thoát.',
    'CG_162_02.167': 'Dù có điên rồ đến đâu chăng nữa...==W== Tôi hiểu rồi. Xem ra tôi đã hiểu vì sao bạn lúc nào cũng can trường táo bạo đến vậy.',
    'CG_162_02.171': '<size=85%>So với cô ấy, mình vẫn còn một chặng đường dài phía trước.</size>',
    'CG_162_02.172': '<size=85%>Được rồi. Mình sẽ lấy cô ấy làm mục tiêu phấn đấu. Trước tiên cứ bắt đầu từ việc làm chủ gian bếp này đã!</size>',
    'CG_162_02.173': 'Dù sao thì...==W== Cảm ơn bạn đã kể cho tôi nghe những chuyện này nhé. Công thức nấu súp tôi đã nắm vững trong lòng bàn tay rồi.',
    'CG_162_02.175': 'Cũng sắp tới lúc nấu món chính rồi. Tôi sẽ vận dụng toàn bộ những gì vừa học được vào đây. Mọi chuyện còn lại cứ giao hết cho tôi.',
    'CG_162_02.176': 'Đ-Được thôi.',
    'CG_162_02.181': 'Alina khí thế hừng hực quá. Mình cũng phải dốc hết sức giúp cô ấy mới được.',
    'CG_162_02.190': 'Chẳng hiểu sao, mình lại chẳng thấy ngạc nhiên chút nào.',
    'CG_162_02.192': 'Tôi đã cẩn thận làm theo từng lời bạn dặn dò rồi mà...',
    'CG_162_02.193': 'Mùi thơm lắm đấy chứ! Trình bày hơi thảm họa một chút đâu có nghĩa là ăn dở đâu nào.',
    'CG_162_02.194': 'Bạn không cần phải gượng ép an ủi tôi đâu. Để tôi đem đổ đống này đi...',
    'CG_162_02.198': 'Xin phép bạn nhé...',
    'CG_162_02.201': 'K-Khoan đã, bạn đang làm gì đấy?! Mau nhổ ra đi! Ăn vào là đau bụng đấy!',
    'CG_162_02.202': 'Mmm...==W== Phần cháy hơi đắng một tí, nhưng càng nhai lại càng thấy bùi. Thật ra ăn cũng không tệ chút nào đâu...?',
    'CG_162_02.203': 'Tôi đã bảo là bạn không cần phải cố ép mình ăn mà!',
    'CG_162_02.204': 'Tôi nói thật mà. Lần này nêm nếm gia vị đậm đà hơn hẳn rồi đấy.',
    'CG_162_02.206': 'Hả? Th-Thật sao...?',
    'CG_162_02.207': 'Ừ. Điểm trừ duy nhất lần này chỉ là canh lửa chưa chuẩn thôi. Rút kinh nghiệm từ lần này, món tiếp theo bạn nấu chắc chắn sẽ tuyệt đỉnh cho xem!',
    'CG_162_02.208': 'Tôi xin lỗi nhé...==W== Bạn dặn là phải đảm bảo mọi thứ đều chín kỹ. Tôi làm theo, nhưng hình như hơi quá tay...',
    'CG_162_02.209': 'Phụt...==W== Hahahaha! Bạn vừa thẳng thắn lại vừa chân thành đáng yêu quá đấy, Alina.',
    'CG_162_02.210': 'Thế thì có gì sai chứ?!',
    'CG_162_02.211': 'Đâu có sai gì đâu. Chỉ là tôi không ngờ lại được thấy một khía cạnh đáng yêu nhường này của bạn thôi.',
    'CG_162_02.213': 'Đ-Đáng yêu á...?!==W== Đừng có trêu chọc tôi nữa mà...!',
    'CG_162_02.214': 'Được rồi, chỉ cần cạo bỏ lớp cháy bên ngoài đi là được. Phần bên trong vẫn ăn ngon lành.',
    'CG_162_02.215': 'Bạn có đang nghe tôi nói không đấy...?==W== Nó cháy thành than củi rồi kìa, thế mà bạn vẫn định ăn à?',
    'CG_162_02.216': 'Ổn mà, đúng không? Như tôi đã nói đấy, hương vị bên trong không hề tệ chút nào. Với lại...',
    'CG_162_02.217': 'Bạn đã dồn hết cả tâm huyết vào món ăn này cơ mà. Cứ thế vứt đi thì phí phạm lắm.',
    'CG_162_02.218': '... Cách dỗ dành động viên người khác này, bạn cũng học từ Noya đấy à?',
    'CG_162_02.219': 'Không đâu, cái này là thương hiệu riêng của tôi đấy nhé.',
    'CG_162_02.220': 'Dù tôi đoán là tính lạc quan của cậu ấy có lẽ cũng lây sang tôi một chút.',
    'CG_162_02.221': 'Người ta bảo rằng khi người nấu cảm thấy vui vẻ, món ăn làm ra cũng sẽ đậm đà thơm ngon hơn đấy.',
    'CG_162_02.222': 'Vui vẻ sao...==W== Có lẽ tôi cũng nên thử mỉm cười nhiều hơn một chút.',
    'CG_162_02.223': 'A nào. Nếm thử một miếng đi, ngon thật mà.',
    'CG_162_02.224': 'Này, đừng coi tôi như con nít thế chứ. Tôi tự ăn đượ—',
    'CG_162_02.232': 'Cư Dân Hốt Hoảng',
    'CG_162_02.233': 'Đại nhân Alina! Đại nhân Alina, xin hãy cứu mạng! Gia đình tôi...==W== Cả nhà tôi bị bắt đi mất rồi!',
    'CG_162_02.236': 'Hãy bình tĩnh lại đã nào. Ai đã bắt họ đi? Bác có biết họ bị đưa đi đâu không?',
    'CG_162_02.237': 'Chính là Caligula! Người của hắn đã lôi cả nhà tôi lẫn hàng xóm vào thẳng trang viên của hắn rồi! Tôi khó khăn lắm mới giữ được mạng mà chạy ra đây...',
    'CG_162_02.238': 'Lại là Caligula...==W== Bác cứ yên tâm. Cháu thề nhất định sẽ đưa mọi người trở về bình an vô sự.',
    'CG_162_02.241': 'Nhưng bạn định làm thế nào đây, Alina? Tôi biết bảo vệ Filanis là chức trách của bạn, và chúng ta đang nắm lẽ phải, nhưng chỉ có hai đứa mình mà đá bay cửa xông thẳng vào thì không phải là nước đi thông minh cho lắm...',
    'CG_162_02.243': 'Chúng ta không cần phải tấn công trực diện. Vài tháng trước, tôi từng triệt phá một băng trộm. Bọn chúng đã đào một đường hầm xuyên qua hang động bên dưới Filanis để đột nhập vào dinh thự của Caligula.',
    'CG_162_02.244': 'Chúng ta có thể dùng đường hầm đó để lén lẻn vào trong.',
    'CG_162_02.245': 'Lẻn vào bằng đường hầm của bọn trộm sao...==W== Nghe giống như đang vượt qua ranh giới đối với một người như bạn đấy nhỉ.',
    'CG_162_02.246': 'Tôi chỉ đang đưa ra một lựa chọn khiến bản thân không phải ân hận mà thôi.',
    'CG_162_02.248': 'Hơn nữa, tôi có bạn ở đây để cùng vượt qua ranh giới đó rồi, đúng không nào?',
    'CG_162_02.249': 'Haha, chuẩn luôn. Tôi sẽ luôn ở ngay bên cạnh bạn.',
    'CG_162_02.253': 'Vậy thì... Xuất phát thôi nào!',

    # ==================== CG_162_03 ====================
    'CG_162_03.4': 'Hồi Ba',
    'CG_162_03.5': 'Cái Tên Của Nàng (Phần III)',
    'CG_162_03.6': 'Trở thành chốn bình yên vỗ về nhau, những ngón tay đan chặt, cùng gìn giữ một bí mật chỉ thuộc về riêng hai chúng ta.',
    'CG_162_03.33': 'Tôi không ngờ những hang động bên dưới Filanis lại rộng lớn đến mức này đấy...',
    'CG_162_03.41': 'Đá ở đây rất dễ bị bào mòn. Qua năm tháng, dòng nước ngầm đã tự đục khoét thành những đường hầm như thế này.',
    'CG_162_03.44': 'Có vẻ như mẹ thiên nhiên cũng muốn tên khốn đó phải đền tội rồi.',
    'CG_162_03.47': 'Nhưng mà sao chúng ta lại hành động vào lúc rạng sáng thế này? Chẳng phải nửa đêm sẽ an toàn hơn sao?',
    'CG_162_03.49': 'Ngược lại hoàn toàn đấy. Đám quý tộc tiệc tùng thâu đêm suốt sáng, phải tới tờ mờ sáng mới chịu đi ngủ. Lúc này chính là thời điểm bọn chúng ngủ say như chết nhất.',
    'CG_162_03.54': 'Nếu thức khuya qua đêm là thành quý tộc, thì chắc tôi đã sống cuộc đời vương giả từ lâu lắm rồi.',
    'CG_162_03.58': 'À mà khoan, đâu có giống nhau. Bọn chúng đâu cần phải leo Cự Tháp hay săn lùng ma vật mỗi ngày như tôi đâu.',
    'CG_162_03.63': '==PLAYER_NAME==, đằng này. Tôi đã mở được lối vào đường hầm rồi.',
    'CG_162_03.83': 'Chờ đã. Ngục tối của Caligula nằm ngay phía trước rồi...==W== Suỵt! Có người ở đó.',
    'CG_162_03.94': 'Kẻ Buôn Nô Lệ Nóng Tính',
    'CG_162_03.95': 'Cái gì cơ?! Hợp đồng bị hủy bỏ á?! Các người không thể làm thế được! Cho ta vào gặp Lãnh chúa Caligula!',
    'CG_162_03.98': 'Lính Gác Quý Tộc',
    'CG_162_03.99': 'Các ngươi để sổng lũ nô lệ mà vẫn còn mặt mũi đòi diện kiến sao? Có biết sai lầm của các ngươi khiến chúng ta tổn thất bao nhiêu thời gian và tiền bạc không hả?',
    'CG_162_03.101': 'Kẻ Buôn Nô Lệ Khả Nghi',
    'CG_162_03.102': 'Suốt bao năm qua là ai đã lùng bắt nô lệ cho các người hả?! Cho dù lần này tao có sơ suất, thì công lao của tao vẫn còn rành rành ra đó!',
    'CG_162_03.106': 'Ngươi chỉ là một tên buôn nô lệ mạt hạng, cẩn thận cái mồm đấy! Lãnh chúa Caligula không còn muốn dính dáng gì đến ngươi nữa. Biến đi cho khuất mắt!',
    'CG_162_03.111': 'Alina, có vẻ như những người dân bị bắt đang bị giam ở trong kia kìa.',
    'CG_162_03.113': '... Tất cả chuyện này là lỗi của tôi sao?',
    'CG_162_03.117': 'Tôi đã cứu hai chị em kia, để rồi giờ đây những người dân vô tội của Filanis lại phải gánh chịu hậu quả thế này...',
    'CG_162_03.119': 'Bạn có hối hận không?',
    'CG_162_03.120': '... Không. Nếu lúc đó tôi cứ thế quay lưng bỏ đi, cả đời này tôi sẽ chẳng bao giờ tha thứ được cho bản thân.',
    'CG_162_03.122': 'Vậy là đủ rồi. Đó chính là chính nghĩa của bạn.',
    'CG_162_03.124': 'Bạn không làm gì sai cả. Tội ác thực sự là đường dây buôn bán nô lệ bẩn thỉu kia, và đám quý tộc sẵn sàng trục lợi từ xương máu đồng loại.',
    'CG_162_03.126': 'Chúng ta đã cứu được hai chị em họ, và giờ chúng ta cũng sẽ giải cứu tất cả những người đang bị giam trong kia.',
    'CG_162_03.127': '... Bạn nói đúng. Bây giờ không phải là lúc để ngồi tự trách mình. Đi thôi nào!',
    'CG_162_03.139': 'Mọi người có sao không? Lính gác đã bị đánh ngất hết rồi. Mau rời khỏi đây nào, giữ im lặng nhé!',
    'CG_162_03.146': 'Người Dân Bị Giam Cầm',
    'CG_162_03.147': 'Bộ quân phục đó...==W== Cô là Người Gác Đêm sao? Tạ ơn trời đất...!==W== Cô đến để giải cứu chúng tôi, đúng không?',
    'CG_162_03.151': 'Mọi người hãy đi sát lại gần nhau. Tôi sẽ dẫn mọi người thoát ra ngoài bằng đường hầm.',
    'CG_162_03.157': 'Cuộc giải cứu diễn ra suôn sẻ đến bất ngờ. Alina và tôi rà soát sạch ngục tối, không bỏ sót lại dù chỉ một người.',
    'CG_162_03.158': 'Chậm lại một chút, không cần vội đâu. Trong này tối lắm, hãy cẩn thận dưới chân.',
    'CG_162_03.159': 'Cô bé này là người cuối cùng rồi. Giờ chỉ còn lại Alina và mình...',
    'CG_162_03.161': 'Cô Bé Khiếm Thị',
    'CG_162_03.162': 'Á! A...',
    'CG_162_03.167': 'Này, có nghe thấy tiếng động gì phát ra từ dưới ngục không?',
    'CG_162_03.168': 'Nguy rồi...!==W== Lính tuần tra đã nghe thấy tiếng động!',
    'CG_162_03.170': 'Cháu xin lỗi! Cháu xin lỗi nhiều lắm! Ch-==W==Cháu...',
    'CG_162_03.177': 'Không phải lỗi của em đâu. Mau đuổi theo mọi người đi. Bọn chị sẽ chặn chúng lại ở đây.',
    'CG_162_03.180': 'Alina, chúng ta chạy theo hướng ngược lại thôi!',
    'CG_162_03.181': 'Rõ rồi!',
    'CG_162_03.186': 'Đằng kia kìa! Đứng lại đó, lũ nô lệ kia! Các ngươi là tài sản thuộc về Lãnh chúa Caligula!',
    'CG_162_03.187': 'Ngươi bảo ai là tài sản hả?! Bắt được bọn này thì hãy nói chuyện nhé!',
    'CG_162_03.188': 'Tốt lắm, kế hoạch thành công rồi. Bọn chúng đều đang đuổi theo chúng ta kìa!',
    'CG_162_03.193': 'Chỉ cần chạy ra được đường lớn, bọn chúng sẽ hết đường cản trở...==W== Oái!',
    'CG_162_03.197': 'Ái ui...!==W== Đi đứng kiểu gì thế hả, không có mắt à! Đang bực cả mình đây!',
    'CG_162_03.199': 'X-Xin lỗi nhé...==W== Ơ kìa, lại là các ngươi?!',
    'CG_162_03.200': 'Hửm? Giọng nói này... Mình từng nghe thấy ở đâu rồi thì phải?',
    'CG_162_03.202': 'Này, chị có sao không thế?',
    'CG_162_03.204': 'Á! Giọng này! Các ngươi chính là lũ thổ phỉ đã cướp đám nô lệ của bọn ta!',
    'CG_162_03.205': 'Khốn thật, sao lại nhằm đúng lúc này cơ chứ...!',
    'CG_162_03.206': 'Hừ. Cung cấp nô lệ cho Lãnh chúa Caligula là vinh hạnh của các ngươi, thế mà còn dám mở mồm đòi tiền sao?',
    'CG_162_03.207': '<size=110%>Biết điều thì cút xéo đi cho rảnh nợ!</size>',
    'CG_162_03.210': 'C-Cái gì, mày vừa sủa cái gì đấy?!',
    'CG_162_03.211': 'Nếu có ý kiến gì thì đi mà nói chuyện với đám lính gác của ta.',
    'CG_162_03.212': 'Đừng tưởng ở cái thành này chỉ có mỗi chúng mày là có người chống lưng! Bọn tao sẽ khiến chúng mày phải hối hận!',
    'CG_162_03.213': 'Alina, người của Caligula tới rồi kìa.',
    'CG_162_03.214': 'Thời cơ chuẩn xác lắm. Chúng ta đi lối này!',
    'CG_162_03.219': 'Đừng hòng trốn thoát!',
    'CG_162_03.221': 'Chúng ở đằng kia kìa! Đứng lại đó, lũ trộm cắp bẩn thỉu kia!',
    'CG_162_03.225': 'Ra là thế...==W== Lãnh chúa Caligula vừa hủy hợp đồng là các ngươi liền thả lũ nô lệ ra để trả thù hả? Đúng là lũ không biết trời cao đất dày là gì!',
    'CG_162_03.228': 'Đồ khốn nạn! Chính Caligula là kẻ nuốt lời, quỵt tiền của bọn tao trước!',
    'CG_162_03.229': 'Câm mồm đi!',
    'CG_162_03.233': 'Đúng là may mắn bất ngờ thật. Giờ thì hai phe bọn chúng đang lao vào cắn xé lẫn nhau rồi...',
    'CG_162_03.235': 'Bọn chúng suýt nữa thì bám sát nút chúng ta. May mà bọn chúng quay sang đấu đá nhau... Đỡ cho mình bao nhiêu rắc rối.',
    'CG_162_03.236': 'Khá lắm đấy chứ.',
    'CG_162_03.237': 'Cái gì khá cơ?',
    'CG_162_03.238': 'Chẳng có gì. Tôi chỉ ấn tượng trước việc bạn bịa chuyện nhanh như chớp thế thôi. Vài ba câu là khiến bọn chúng quay sang choảng nhau tơi bời rồi.',
    'CG_162_03.240': 'Thế là lỗi của ai hả? Ở cạnh bạn riết rồi tôi thấy mình cũng nhiễm thói hư tật xấu theo luôn rồi đấy.',
    'CG_162_03.241': 'Dù rằng...==W== cảm giác lúc này cũng chẳng tệ chút nào.',
    'CG_162_03.243': 'Với lại...==W== Về chuyện ngày hôm nay...',
    'CG_162_03.246': 'Tôi biết rồi mà. Bí mật chỉ riêng hai đứa mình biết thôi, đúng chứ?',
    'CG_162_03.248': 'Cảm ơn bạn nhé.',
    'CG_162_03.251': 'Đây là...==W== Nhà Tắm Olympia sao? Alina, sao chúng ta lại tới đây?',
    'CG_162_03.253': 'Để trốn đấy. Tôi đã nhờ Lulu sắp xếp cho chúng ta một phòng tắm riêng tư, nơi bình thường chỉ dành riêng cho giới quý tộc thôi.',
    'CG_162_03.254': 'Nếu người của Caligula nhận ra bọn chúng bắt nhầm người, chúng sẽ chẳng bao giờ ngờ được thủ phạm thực sự lại đang thảnh thơi ngâm mình tắm táp đâu.',
    'CG_162_03.255': 'Hơn nữa, chúng ta vừa mới lăn lộn trong hang động bụi bặm đầy người. Đây là lúc thích hợp nhất để tắm rửa sạch sẽ, tiện thể tiêu hủy luôn mọi dấu vết bằng chứng...',
    'CG_162_03.256': 'Nghe cũng có lý đấy...==W== K-Khoan đã, Alina?! Sao bạn lại cởi giáp ra thế kia...?',
    'CG_162_03.259': 'Không cởi ra thì tắm thế nào được hả bạn? Nhanh lên đi chứ.',
    'CG_162_03.262': 'Một bồn tắm sang trọng thế này...==W== Cũng nhờ có bạn mà tôi mới được hưởng ké đấy.',
    'CG_162_03.269': 'Hơi nước ấm áp lan tỏa,==W== hương hoa thoang thoảng dịu êm...==W== Thật dễ chịu làm sao.',
    'CG_162_03.270': 'Hơi nước ấm áp lan tỏa,==W== hương hoa thoang thoảng dịu êm…==W== Hóa ra đây chính là cảm giác được chữa lành.',
    'CG_162_03.273': 'Alina, lưng của bạn... Bạn bị thương sao?',
    'CG_162_03.278': 'Bị thương á?==W== Tôi đâu có...==W== À, ý bạn là những vết sẹo cũ này sao?',
    'CG_162_03.279': 'Nếu là chúng,==W== thì chúng không còn đau nữa đâu,==W== nên bạn đừng lo lắng nhé.',
    'CG_162_03.280': 'Nếu là chúng, thì chúng không còn đau nữa đâu,==W== nên bạn đừng lo lắng nhé.',
    'CG_162_03.282': 'Vết sẹo cũ ư? Từ hồi bạn còn làm giác đấu sĩ sao?',
    'CG_162_03.284': 'Đúng vậy.==W== Nhưng mà==W== vết thương của tôi lúc nào cũng lành rất nhanh,==W== nên hầu hết thương tích đều chẳng để lại chút dấu vết nào==W== nếu cứ mặc kệ nó…',
    'CG_162_03.285': 'Đúng vậy.==W== Nhưng mà==W== vết thương của tôi lúc nào cũng lành rất nhanh,==W== nên hầu hết thương tích đều chẳng để lại chút dấu vết nào nếu cứ mặc kệ nó…',
    'CG_162_03.286': 'Những vết này ắt hẳn phải sâu lắm đấy==W== Cơ mà,==W== chúng cũng sẽ mờ dần từng chút một thôi,==W== nên không cần==W== phải bận tâm đâu.',
    'CG_162_03.287': 'Những vết này ắt hẳn phải sâu lắm,==W== thế nên mới còn lưu lại sẹo thế này.==W== Cơ mà, chúng cũng sẽ mờ dần từng chút một thôi,==W== nên không cần phải bận tâm đâu.',
    'CG_162_03.289': 'Hóa ra bạn cũng thuộc tuýp người khó để lại sẹo à.',
    'CG_162_03.291': '"Cũng" ư?==W== Chẳng lẽ người tên Noya mà bạn bảo rất giống tôi đó,==W== cũng như vậy sao?',
    'CG_162_03.292': '"Cũng" ư?==W== Chẳng lẽ người tên Noya,==W== người mà bạn bảo rất giống tôi, cũng như vậy sao?',
    'CG_162_03.293': '… Thật tình,==W== lúc nào bạn cũng Noya thế này, Noya thế nọ.==W== Người kề vai sát cánh cùng bạn vượt qua hoạn nạn đâu phải là Noya, mà là tôi cơ mà…',
    'CG_162_03.294': '… Thật tình,==W== lúc nào bạn cũng Noya thế này, Noya thế nọ.==W== Người kề vai sát cánh cùng bạn vượt qua hoạn nạn==W== đâu phải là Noya, mà là tôi cơ mà…',
    'CG_162_03.295': 'Đối với bạn,==W== tôi chỉ là người để lấp đầy nỗi cô đơn khi không thể gặp lại cô ấy thôi sao? Một kẻ thay thế, có phải vậy không?',
    'CG_162_03.297': 'Không! Hoàn toàn không phải vậy đâu!',
    'CG_162_03.299': 'Tôi chưa bao giờ coi bạn là người thay thế cho bất kỳ ai cả.',
    'CG_162_03.301': 'Hì hì...==W== Không sao đâu mà.',
    'CG_162_03.302': 'Nếu bạn nhìn thấy hình bóng của cô ấy nơi tôi,==W== điều đó chỉ chứng minh rằng==W== những ký ức bạn từng sẻ chia cùng cô ấy vẫn luôn in sâu nơi đáy lòng bạn.',
    'CG_162_03.303': 'Nếu bạn nhìn thấy hình bóng của cô ấy nơi tôi,==W== điều đó chỉ chứng minh rằng những ký ức bạn từng sẻ chia cùng cô ấy vẫn luôn in sâu nơi đáy lòng bạn.',
    'CG_162_03.304': 'Chẳng bù cho tôi...==W== kẻ thậm chí còn chẳng thể nhớ nổi gương mặt của những người đồng đội==W== từng cùng mình kề vai chiến đấu vào sinh ra tử thuở nào…',
    'CG_162_03.305': 'Còn tôi thì thậm chí còn chẳng thể nhớ nổi gương mặt của những người đồng đội từng cùng mình kề vai chiến đấu…==W== Thật tốt khi bạn không giống như tôi…',
    'CG_162_03.309': 'Tôi... từng nâng niu những vết sẹo cũ này==W== trên cơ thể mình như những kỷ vật thiêng liêng dâng tặng cho những đồng đội==W== đã ngã xuống nơi đấu trường cát bụi.',
    'CG_162_03.310': 'Tôi...==W== từng nâng niu những vết sẹo cũ này trên cơ thể mình==W== như những kỷ vật thiêng liêng dâng tặng cho những đồng đội đã ngã xuống nơi đấu trường.',
    'CG_162_03.311': 'Thế nhưng...==W== Khi những vết sẹo bắt đầu mờ dần,==W== thì những khung cảnh của những tháng ngày xưa cũ ấy cũng dần phai nhạt theo.',
    'CG_162_03.312': 'Nói thật lòng thì,==W== tôi ghen tị với bạn lắm đấy.==W== Bạn vẫn còn có một người để ngày đêm mong mỏi gặp lại.',
    'CG_162_03.313': 'Nói thật lòng thì,==W== tôi ghen tị với bạn lắm đấy.==W== Bạn vẫn còn có==W== một người để ngày đêm tha thiết ngóng trông.',
    'CG_162_03.314': 'Còn tôi thì chẳng còn==W== một ai như thế trên đời này nữa rồi…',
    'CG_162_03.316': 'Bạn còn có tôi mà.',
    'CG_162_03.318': 'Hì hì... ==W==Bạn đúng là==W== khéo ăn khéo nói thật đấy.',
    'CG_162_03.319': 'Hì hì...==W== Bạn đúng là==W== khéo ăn khéo nói thật đấy.',
    'CG_162_03.320': 'Ở bên cạnh bạn,==W== tôi chỉ muốn cứ thế vượt qua mọi ranh giới mãi thôi.==W== Bạn đúng là... một người khó trị thật đấy.',
    'CG_162_03.321': 'Ở bên cạnh bạn,==W== tôi chỉ muốn cứ thế vượt qua mọi ranh giới mãi thôi.==W== Bạn đúng là...==W== một người khó trị thật đấy.',
    'CG_162_03.327': 'Alina khẽ lảng tránh chủ đề ấy. Cô cởi bỏ nốt phần y phục còn lại rồi kéo tôi vào bồn tắm riêng tư chỉ thuộc về hai đứa.',
    'CG_162_03.329': 'Tôi không rõ cô ấy đang nghĩ suy điều gì, nhưng khi cả hai cùng ngâm mình trong làn nước ấm, cô vẫn đan chặt những ngón tay mình vào tay tôi.',
    'CG_162_03.330': 'Những ngón tay nàng thật thon thả, nhưng cái nắm tay lại kiên định và ấm áp biết bao.',
    'CG_162_03.331': 'Về sau, tội ác của Caligula bị vạch trần trước bàn dân thiên hạ. Thế nhưng câu chuyện của ngày hôm ấy vẫn mãi là một bí mật, một bí mật chỉ thuộc về riêng hai chúng tôi.',
    'CG_162_03.333': 'Giá như... mình có thể trở thành "Noya" của bạn.',
}
